import{_ as o,o as a,c as r,a3 as n}from"./chunks/framework.CWSmAuPU.js";const u=JSON.parse('{"title":"0021 npm 分发：全局包是版本管理器，各版本仍装在 versions/ 下","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0021-npm-version-manager.md","filePath":"reference/adr/0021-npm-version-manager.md","lastUpdated":null}'),i={name:"reference/adr/0021-npm-version-manager.md"};function t(d,e,s,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<div><h1 id="_0021-npm-分发-全局包是版本管理器-各版本仍装在-versions-下" tabindex="-1">0021 npm 分发：全局包是版本管理器，各版本仍装在 versions/ 下 <a class="header-anchor" href="#_0021-npm-分发-全局包是版本管理器-各版本仍装在-versions-下" aria-label="Permalink to &quot;0021 npm 分发：全局包是版本管理器，各版本仍装在 versions/ 下&quot;">​</a></h1><ul><li>状态：已采纳（在 <a href="./0009-versioned-install-layout">0009</a>、<a href="./0016-upgrade-from-tags">0016</a> 的基础上增加 npm 来源）</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>git 安装要 clone、npm install、运行安装器三步，Windows 上还要自己把 <code>~/.req-kit/bin</code> 加进 PATH。npm 全局安装能解决这两点，但 <code>npm i -g</code> 升级时原地覆盖：正在运行的流水线每个步骤都从磁盘读提示词，会混用新旧版本，也失去了&quot;旧版本目录保留、随时回滚&quot;的保证（0009）。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li>只发布一个包 <code>paseo-req-kit</code>。用 <code>npm i -g</code> 安装的那一份是<strong>版本管理器</strong>：<code>req setup</code>、<code>req upgrade</code>、<code>req use</code>、<code>req versions</code> 由它处理，其他命令转交给 <code>~/.req-kit/active.json</code> 指向的版本。</li><li>版本仍装在 <code>~/tools/req-kit/versions/&lt;版本&gt;</code>，用 <code>npm install --prefix versions/&lt;版本&gt; paseo-req-kit@&lt;版本&gt;</code> 安装，程序在其中的 <code>node_modules/paseo-req-kit</code>。<code>req setup</code> 用 <code>npm pack</code> 把管理器自己装进去，不必再从仓库下载一次。</li><li><code>req upgrade</code> 从 npm 读版本列表，用本机 daemon 报告的版本和每个版本声明的 <code>reqKit.paseo</code> 范围筛选，只升级到能支持本机 Paseo 的版本。正式版另设 <code>paseo-&lt;小版本&gt;</code> dist-tag，供手工安装。</li><li>git 方式安装继续支持，默认来源按安装方式决定，<code>--from</code> 可以改。</li><li>发布由 GitHub Actions 在标签推送时完成，使用 npm 可信发布（OIDC），不保存 npm 口令；Release 附带 <code>npm pack</code> 的安装包供离线和内网仓库使用。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><p>安装变成两条命令，PATH 由 npm 处理。管理器自身很少需要升级（<code>npm i -g paseo-req-kit</code> 即可），版本切换不受影响。读不到 daemon 版本时不能按 Paseo 版本筛选，会提示并在升级后建议体检。</p></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0021-npm-version-manager.md">docs/adr/0021-npm-version-manager.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0021-npm-version-manager.md">在 GitHub 上编辑</a></p>',2)])])}const h=o(i,[["render",t]]);export{u as __pageData,h as default};
